const normalizePhone = (phoneInput) => {
  let phone = (phoneInput || "").replace(/\D/g, "");

  if (phone.startsWith("00")) {
    phone = phone.slice(2);
  }

  if (phone.length === 10 && /^[6-9]/.test(phone)) {
    phone = "91" + phone;
  }

  let locale = "in";

  for (let prefixLen = 3; prefixLen >= 1; prefixLen--) {
    const prefix = phone.substring(0, prefixLen);
    const rule = DIAL_CODES[prefix];

    if (rule) {
      const nationalLength = phone.length - prefixLen;

      if (rule.len.includes(nationalLength)) {
        locale = rule.iso;
        break;
      }
    }
  }

  return {
    phoneNumber: phone,
    locale: locale,
  };
};

window.normalizePhone = normalizePhone;

function getDoctorDetailInfo() {
  function getText(selector) {
    var element = document.querySelector(selector);

    return element ? element.innerText.replace(/\s+/g, " ").trim() : "";
  }

  // Doctor Container

  var doctorCard = document.querySelector("[id^='doctor-']");

  if (!doctorCard) {
    return null;
  }

  // Doctor IDs

  var doctorId = (doctorCard.id || "").replace("doctor-", "");

  var hospitalId = (doctorCard.getAttribute("data-hospitalid") || "").replace(
    "hospital-",
    "",
  );

  var specialityId = (
    doctorCard.getAttribute("data-specialityid") || ""
  ).replace("speciality-", "");

  var cityId = (doctorCard.getAttribute("data-cityid") || "").replace(
    "city-",
    "",
  );

  // Doctor Name

  var doctorName = getText(".doctor_d_name_inner");

  // Speciality

  var speciality = getText(".doctor_d_desc")
    .replace(/\s*:\s*$/, "")
    .replace(/&/g, "and")
    .replace(/\s+/g, " ")
    .trim();

  // Qualification

  var qualification = getText(".doctor_d_educ")
    .replace(/^Education:\s*/i, "")
    .trim();

  // Languages

  var languages = [];

  var languageContainer = document.querySelector(".doctor_d_lang");

  if (languageContainer) {
    var languageSpans = languageContainer.querySelectorAll("span");

    for (var i = 0; i < languageSpans.length; i++) {
      var language = languageSpans[i].innerText.replace(/\s+/g, " ").trim();

      if (language && languages.indexOf(language) === -1) {
        languages.push(language);
      }
    }
  }

  // Experience

  var experienceText = getText(".doctor_d_exper");

  var yearsOfExperience = 0;

  var experienceMatch = experienceText.match(/\d+/);

  if (experienceMatch) {
    yearsOfExperience = parseInt(experienceMatch[0], 10);
  }

  // Consultation Details

  var timingText = getText(".doctor_d_timing");

  var consultationHours = "";

  var consultationDays = "";

  var timingMatch = timingText.match(/(\d{1,2}:\d{2}\s*-\s*\d{1,2}:\d{2})/);

  if (timingMatch) {
    consultationHours = timingMatch[1];

    consultationDays = timingText.replace(consultationHours, "").trim();
  }

  // Doctor Image

  var imageUrl = "";

  var imageElement = document.querySelector(".doctor_image_top_img");

  if (imageElement) {
    imageUrl = imageElement.src || "";
  }

  // Hospital Details

  var hospitalName = "";

  var hospitalAddress = "";

  var hospitalRadio = document.querySelector(
    "input[name='doctors_page_city']:checked",
  );

  if (hospitalRadio) {
    hospitalName = hospitalRadio.getAttribute("data-hospital-name") || "";

    hospitalAddress = hospitalRadio.getAttribute("data-hospital-address") || "";
  }

  // City Name

  var city = "";

  var cityContainer = document.querySelector("#select2-edit-city-container");

  if (cityContainer) {
    var selectedCity = cityContainer.innerText.replace("×", "").trim();

    if (selectedCity && selectedCity.toLowerCase() !== "select city") {
      city = selectedCity;
    }
  }

  // Fallback 1 - URL Slug

  if (!city) {
    var pathParts = window.location.pathname.split("/").filter(Boolean);

    if (pathParts.length >= 3) {
      city = pathParts[2]
        .split("-")
        .map(function (word) {
          return word.charAt(0).toUpperCase() + word.slice(1);
        })
        .join(" ");
    }
  }

  // Fallback 2 - Hospital Name

  if (!city && hospitalName) {
    var hospitalParts = hospitalName.split(",");

    if (hospitalParts.length > 1) {
      city = hospitalParts[hospitalParts.length - 1].trim();
    }
  }

  // Return Object

  return {
    doctorId: doctorId,

    hospitalId: hospitalId,

    specialityId: specialityId,

    cityId: cityId,

    doctorName: doctorName,

    speciality: speciality,

    qualification: qualification,

    languages: languages,

    yearsOfExperience: yearsOfExperience,

    consultationHours: consultationHours,

    consultationDays: consultationDays,

    hospital: hospitalName,

    hospitalAddress: hospitalAddress,

    city: city,

    imageUrl: imageUrl,

    doctorUrl: window.location.href,
  };
}
